def parse_duration(text: str) -> float:
    if not text or not text.startswith('P'):
        raise ValueError("Duration must start with 'P'")

    # Remove the 'P' prefix
    text = text[1:]

    if not text:
        raise ValueError("Duration must have at least one component")

    # Split into date and time parts
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one time component")
    else:
        date_part = text
        time_part = ""

    total_seconds = 0.0

    # Parse date part
    if date_part:
        if 'Y' in date_part or 'M' in date_part:
            raise ValueError("Years and months are not supported")

        # Check for weeks
        if 'W' in date_part:
            if 'D' in date_part:
                raise ValueError("Cannot have both weeks and days")
            # Parse weeks - should be format like "1W"
            parts = date_part.split('W')
            if len(parts) != 2 or parts[1] != '':
                raise ValueError("Invalid week format")
            if not parts[0]:
                raise ValueError("Week component must have a value")
            try:
                weeks = float(parts[0])
                if weeks < 0:
                    raise ValueError("Negative values not allowed")
                total_seconds += weeks * 7 * 86400
            except ValueError:
                raise ValueError("Invalid week value")
        elif 'D' in date_part:
            # Parse days - should be format like "1D"
            parts = date_part.split('D')
            if len(parts) != 2 or parts[1] != '':
                raise ValueError("Invalid day format")
            if not parts[0]:
                raise ValueError("Day component must have a value")
            try:
                days = float(parts[0])
                if days < 0:
                    raise ValueError("Negative values not allowed")
                total_seconds += days * 86400
            except ValueError:
                raise ValueError("Invalid day value")
        else:
            raise ValueError("Invalid date format")

    # Parse time part
    if time_part:
        # Process H, M, S components
        remaining = time_part

        if 'H' in remaining:
            parts = remaining.split('H', 1)
            if not parts[0]:
                raise ValueError("Hour component must have a value")
            try:
                hours = float(parts[0])
                if hours < 0:
                    raise ValueError("Negative values not allowed")
                total_seconds += hours * 3600
            except ValueError:
                raise ValueError("Invalid hour value")
            remaining = parts[1]

        if 'M' in remaining:
            parts = remaining.split('M', 1)
            if not parts[0]:
                raise ValueError("Minute component must have a value")
            try:
                minutes = float(parts[0])
                if minutes < 0:
                    raise ValueError("Negative values not allowed")
                total_seconds += minutes * 60
            except ValueError:
                raise ValueError("Invalid minute value")
            remaining = parts[1]

        if 'S' in remaining:
            parts = remaining.split('S', 1)
            if not parts[0]:
                raise ValueError("Second component must have a value")
            if parts[1] != '':
                raise ValueError("Invalid character after seconds")
            try:
                seconds = float(parts[0])
                if seconds < 0:
                    raise ValueError("Negative values not allowed")
                total_seconds += seconds
            except ValueError:
                raise ValueError("Invalid second value")
            remaining = ''

        if remaining:
            raise ValueError("Invalid time format")

    if total_seconds == 0:
        raise ValueError("At least one component must be present")

    return total_seconds
